<?php
declare(strict_types=1);define('_GNUBOARD_',true);
if(!str_contains((string)getenv('NOA_MYSQL_DSN'),'dbname=noa_workspace_test;'))throw new RuntimeException('isolated_database_required');
require __DIR__.'/../../bridge/storage.php';require __DIR__.'/../../bridge/youtube-store.php';require __DIR__.'/../../bridge/record-trash.php';require __DIR__.'/../../bridge/library-records.php';
require __DIR__.'/../../deploy/noa-app/jukebox/core.php';
$db=noa_bridge_pdo();function must($ok,$why){if(!$ok)throw new RuntimeException($why);}
$id=str_repeat('a',64);$records=ncl_records($db,true);must(count($records)===3&&$records[$id]['title']==='검색 검증곡','canonical_title_and_no_duplicate');must($records[$id]['fields']['songDescription']==='기존 소개','song_intro_separate_from_youtube_description');must(count(ncl_records($db,false))===2,'private_canonical_record_not_published_by_snapshot');
$source=$db->query('SELECT fields_json FROM noa_catalog_versions ORDER BY entity_id')->fetchAll(PDO::FETCH_COLUMN);$before=$db->query("SELECT payload FROM noa_documents WHERE doc_key='story:test'")->fetchColumn();
$request=['action'=>'trash','selector'=>['type'=>'song','source'=>'music','key'=>'story:test'],'expectedRevision'=>1,'requestId'=>'11111111-1111-1111-1111-111111111111'];
$next=nrt_change($db,$request,'fixture');must($next['revision']===2,'trash_revision');must(nrt_change($db,$request,'fixture')['replayed'],'idempotent');must(!isset(ncl_records($db,true)[$id])&&!isset(ncl_records($db,false)[$id]),'deleted_hidden_from_normal_library');must(count(ncl_records($db,true,'',true))===1,'trash_only_deleted');
must(nj_document($db,'story:test')===null&&!isset(nj_catalog($db)['story:test']),'deleted_hidden_from_jukebox_selection_and_stream');
$index=noa_sound_trash_index($db,true);must(isset($index['keys']['story:test'],$index['ids'][$id],$index['videos']['abcdefghijk']),'identity_and_video_tombstones');must(!isset(ny_songs($db,str_repeat('f',64))[$id]),'youtube_projection_hidden');
try{nrt_change($db,array_replace($request,['action'=>'restore','requestId'=>'22222222-2222-2222-2222-222222222222']),'fixture');throw new RuntimeException('stale_revision_accepted');}catch(DomainException $e){must($e->getMessage()==='revision_conflict','stale_restore_rejected');}
$restored=nrt_change($db,array_replace($request,['action'=>'restore','expectedRevision'=>2,'requestId'=>'33333333-3333-3333-3333-333333333333']),'fixture');must($restored['revision']===3,'restore_revision');$after=$db->query("SELECT payload FROM noa_documents WHERE doc_key='story:test'")->fetchColumn();must(json_decode($before,true)===json_decode($after,true),'exact_original_restored');noa_sound_trash_index($db,true);must(isset(ncl_records($db,false)[$id]),'visible_after_restore');must(nj_document($db,'story:test')!==null&&isset(nj_catalog($db)['story:test']),'jukebox_visible_after_restore');must($source===$db->query('SELECT fields_json FROM noa_catalog_versions ORDER BY entity_id')->fetchAll(PDO::FETCH_COLUMN),'immutable_snapshots_preserved');must((int)$db->query("SELECT COUNT(*) FROM noa_document_history WHERE doc_key='story:test'")->fetchColumn()===3,'exactly_one_history_per_mutation');
echo "WORKSPACE_CANONICAL_PRIVACY_TRASH_RESTORE_CAS_IDEMPOTENCE_AND_SNAPSHOTS_OK\n";
